const sign=l=>Math.floor(norm(l)/30);
const sep=(a,b)=>{const d=Math.abs(norm(a)-norm(b));return Math.min(d,360-d)};
const cyc=(s,b)=>{for(let i=0;i<60;i++)if(i%10===s&&i%12===b)return i};
const pillar=i=>ST[mod(i,60)%10]+BR[mod(i,60)%12];
function tenGod(d,o){const rel=mod(SE[o]-SE[d],5),same=(d%2)===(o%2);return TG[rel*2+(same?0:1)]}
const digitsum=n=>String(n).split("").reduce((a,b)=>a+ +b,0);
function reduceNum(n,master){while(n>9&&!(master&&(n===11||n===22||n===33)))n=digitsum(n);return n}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
