const SL=1.2;
/* 점술·운별 기본값 보정: 무작위 출생 300명×81년 평균이 기준점 근처가 되도록 맞춘 값 */
const OCAL=[[-6.4,-5.7,-21.2,1.2],[-4.5,-1.7,-6.6,4.9],[-10.6,-6.2,-15.1,5.3],[-7.2,-14.2,-15.7,-12.1],[-7.2,-10.6,-15.4,-11.9],[-13.4,-17,-18.7,-14.1]];
function horizonDate(off){const y=Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Seoul',year:'numeric'}).format(new Date()))+off;return {y,frac:y+.5}}
function lifeDate(ch,age){const frac=ch.birthYear+age+.5;return {y:Math.floor(frac),frac}}
function fin(raw,F,oi,ci){return [stretch(raw+OCAL[oi][ci]),F.filter(f=>Math.abs(f[1])>=.5).map(f=>[f[0],Math.round(f[1]*SL)])]}
const sumF=F=>F.reduce((a,f)=>a+f[1],0);
function oSaju(ch,t,ci){const {y,frac}=t;const age=frac-ch.birthYear;
  const s=mod(y-4,10),b=mod(y-4,12),d=ch.stems.d;const pre=age<ch.dwStart;
  let dw;if(pre)dw=ch.mIdx;else{const k=Math.floor((age-ch.dwStart)/10)+1;dw=ch.mIdx+(ch.fwd?k:-k)}
  const dwS=mod(dw,60)%10,dwB=mod(dw,60)%12,dl=pre?"월주":"대운";
  const t1=tenGod(d,s),t2=tenGod(d,BMAIN[b]),t3=tenGod(d,dwS),t4=tenGod(d,BMAIN[dwB]);
  const idx=[0,ch.male?1:2,3,4][ci];const w=tg=>TGW[tg][idx];const grp=tg=>Math.floor(TG.indexOf(tg)/2);const fav=tg=>ch.goodG.includes(grp(tg));
  const F=[[`${ST[s]} ${t1}`,w(t1)*.7],[`${BR[b]} ${t2}`,w(t2)*.55],[`${dl} ${ST[dwS]} ${t3}`,w(t3)*.45],[`${dl} ${BR[dwB]} ${t4}`,w(t4)*.3]];
  const yong=[[t1,7,4],[t2,5,3],[t3,5,3],[t4,3,2]].reduce((a,[tg,p,n])=>a+(fav(tg)?p:-n),0);
  F.push([ch.strong?"신강 사주에 맞는 기운":"신약 사주에 맞는 기운",yong]);
  let extra="";const db=ch.brs.d;
  if((b+db)%12===1){F.push([`${BR[b]}${BR[db]}합`,[6,18,4,6][ci]]);extra+=` 그해 지지가 배우자 자리(${BR[db]})와 합해 ${["돈이 모이고 묶입니다","인연이 단단히 맺어집니다","협력이 잘 됩니다","마음이 안정됩니다"][ci]}.`}
  if(Math.abs(b-db)===6){F.push([`${BR[b]}${BR[db]}충`,-[4,12,0,8][ci]]);extra+=` 그해 지지가 배우자 자리(${BR[db]})와 충해 ${["돈의 흐름이 바뀝니다. 새 판을 짤 기회입니다","관계에 새 바람이 붑니다. 더 맞는 쪽으로 정리됩니다","자리 이동이나 새 도전이 열립니다","생활 리듬을 바꾸기 좋은 때입니다"][ci]}.`}
  if(ch.gui.includes(b)){F.push(["천을귀인의 해",[8,8,8,8][ci]]);extra+=" 천을귀인이 드는 해라 결정적인 순간에 귀인이 나타납니다."}
  if(b===ch.munc&&ci===2){F.push(["문창귀인의 해",10]);extra+=" 문창귀인이 들어 시험·공부·글에서 빛납니다."}
  if(b===ch.dohwa&&ci===1){F.push(["도화의 해",10]);extra+=" 도화가 드는 해라 매력이 가장 돋보입니다."}
  if(b===ch.yeokma&&(ci===0||ci===2)){F.push(["역마의 해",ci===2?6:4]);extra+=" 역마가 움직여 이동·출장·해외에서 기회가 옵니다."}
  const main=Math.abs(w(t1))>=Math.abs(w(t2))?[ST[s],t1]:[BR[b],t2];
  let p=TGP[main[1]][CATS[ci].k];
  if(ci===1){const isMate=ch.male?["편재","정재"].includes(main[1]):["편관","정관"].includes(main[1]);if(isMate)p=`${ch.male?"남성 사주에서 재성":"여성 사주에서 관성"}은 이성 인연을 뜻합니다. ${p}`}
  if(yong>=8)p+=". 내 사주에 꼭 필요한 기운이 들어오는 해라 운이 한층 밝아집니다";
  const [sc,FF]=fin(52+sumF(F),F,0,ci);
  return [sc,`${p}.${extra}<small class="reading-basis">${pillar(cyc(s,b))}년 · ${main[0]}(${main[1]})</small>`,`${pillar(cyc(s,b))}년 · ${pillar(dw)} ${dl}`,FF]}
function oWest(ch,t,ci){const {frac}=t;const jd=jdUTC(Math.floor(frac),Math.floor((frac%1)*12)+1,1,0);
  const J=jupLon(jd),S=satLon(jd);const base=sign(ch.asc??ch.sun);const hJ=mod(sign(J)-base,12)+1,hS=mod(sign(S)-base,12)+1;
  const top=HOUSE[hJ],stp=HOUSE[hS];const F=[[`목성 ${hJ}H ${top}`,JW[hJ][ci]],[`토성 ${hS}H ${stp}`,SW[hS][ci]*.8]];const notes=[];
  if(sep(S,ch.natSat)<14){F.push(["토성 회귀",[2,-2,12,-6][ci]]);notes.push("토성이 태어날 때 자리로 돌아오는 토성 회귀 구간이에요. 진짜 어른으로 거듭나며 인생의 기반을 새로 세웁니다")}
  if(sep(J,ch.natJup)<10){F.push(["목성 회귀",[10,8,10,6][ci]]);notes.push("목성이 태어날 때 자리로 돌아오는 목성 회귀예요. 12년 만에 행운의 주기가 새로 시작됩니다")}
  const jHit=sep(J,ch.sun)<10?"태양":(ch.asc!=null&&sep(J,ch.asc)<10)?"상승궁":null;
  if(jHit){F.push([`목성·출생 ${jHit}`,10]);notes.push(`목성이 출생 ${jHit} 위를 지나는 12년 만의 행운 구간입니다`)}
  else if(Math.abs(sep(J,ch.sun)-120)<8){F.push(["목성·태양 삼각",6]);notes.push("목성이 태양과 조화로운 각도(트라인)를 이뤄 일이 순조롭게 풀립니다")}
  if(Math.abs(sep(S,ch.sun)-90)<6||Math.abs(sep(S,ch.sun)-180)<6){F.push(["토성·태양 긴장각",[-2,-2,-4,-4][ci]]);notes.push("토성이 태양과 긴장 각도를 이뤄 한 단계 성숙해지는 관문을 지납니다")}
  const jv=JW[hJ][ci],sv=SW[hS][ci];
  const jp=jv>=20?`${top} 쪽 기회가 크게 열립니다`:jv>=8?`${top} 쪽에 순풍이 붑니다`:jv>-5?`${top}을 통해 은근한 행운이 들어옵니다`:`${top}에서 쉬어가며 다음 기회를 준비합니다`;
  const spp=sv<=-15?`${stp}에서 성숙의 시험을 지나며 큰 내공이 쌓입니다`:sv<=-5?`${stp}에 꾸준함을 들인 만큼 단단해집니다`:sv>=10?"책임진 만큼 확실한 결과를 남깁니다":"든든하게 받쳐줍니다";
  const [sc,FF]=fin(52+sumF(F),F,1,ci);
  return [sc,`${jp}. ${spp}.${notes.length?" "+notes.join(". ")+".":""}<small class="reading-basis">목성 ${hJ}하우스(${top}) · 토성 ${hS}하우스(${stp})</small>`,`목성 ${ZOD[sign(J)]} · 토성 ${ZOD[sign(S)]}`,FF]}
function oVedic(ch,t,ci){const {frac}=t;const md=ch.dashas.find(x=>frac>=x.start&&frac<x.end)||ch.dashas[ch.dashas.length-1];
  let st=md.start,ad=null;for(let k=0;k<9;k++){const L=(md.L+k)%9;const len=DY[md.L]*DY[L]/120;if(frac<st+len){ad={lord:DL[L],end:st+len};break}st+=len}
  ad=ad||{lord:md.lord,end:md.end};
  const F=[[`대운 ${PK[md.lord]}`,PW[md.lord][ci]*.5],[`보조 ${PK[ad.lord]}`,PW[ad.lord][ci]*.75],[`${PK[md.lord]}·${ch.prole[md.lord]}`,ch.FW[md.lord][ci]*.5],[`${PK[ad.lord]}·${ch.prole[ad.lord]}`,ch.FW[ad.lord][ci]*.75]];
  const endY=Math.floor(ad.end),endM=Math.floor((ad.end%1)*12)+1;const [sc,FF]=fin(50+sumF(F),F,2,ci);
  const role=["라그나 주인","요가카라카","행운 하우스 주인"].includes(ch.prole[ad.lord])?` 당신의 차트에서 ${PK[ad.lord]}은 ${ch.prole[ad.lord]} 행성이라 특히 힘이 셉니다.`:"";
  return [sc,`${PP[ad.lord][ci]}.${role}<small class="reading-basis">${PK[md.lord]} 대운 · ${PK[ad.lord]} 기간(~${endY}.${endM})</small>`,`${PK[md.lord]}–${PK[ad.lord]} 다샤`,FF]}
function oNum(ch,t,ci){const {y}=t;const py=reduceNum(reduceNum(ch.Mo,false)+reduceNum(ch.D,false)+reduceNum(digitsum(y),false),false);
  const lpAdj={money:{8:6,4:4,22:6},love:{2:6,6:6,33:6},work:{1:5,8:5,22:6,11:4},health:{6:3,9:3}}[CATS[ci].k][ch.lp]||0;
  const F=[[`개인년 ${py}`,NYW[py][ci]-50]];if(lpAdj)F.push([`인생 수 ${ch.lp}`,lpAdj]);if(py===ch.lp%9||(py===9&&ch.lp%9===0))F.push(["인생 수와 공명",5]);
  const [sc,FF]=fin(50+sumF(F),F,3,ci);
  return [sc,`${NYP[py][ci]}.<small class="reading-basis">${y}년 · 개인년 ${py}</small>`,`개인년 ${py}`,FF]}
/* 마야력: 전통 촐킨(GMT 584283). 그해 운은 260일마다 돌아오는 탄생일(같은 숫자·같은 기호)이 그해에 몇 번 드는지로 본다 */
function kinReturns(ch,y){const kb=mod(jdn(ch.Y,ch.Mo,ch.D)-584283,260),J0=jdn(y,1,1),J1=jdn(y+1,1,1);const out=[];let d=J0+mod(kb-mod(J0-584283,260),260);while(d<J1){out.push(d);d+=260}return out}
function oMaya(ch,t,ci){const {y}=t;const rt=kinReturns(ch,y);const ds=rt.map(j=>{const [,m,dd]=jdnToDate(j);return `${m}/${dd}`}).join(", ");
  const F=[[`탄생 기호 ${MS[ch.msign][0]}(${MS[ch.msign][1]})`,MS[ch.msign][3][ci]-50],[`탄생 숫자 ${ch.tone} ${MT[ch.tone][0]}`,MT[ch.tone][1][ci]],[`탄생일 ${rt.length}번`,rt.length>=2?8:2]];
  const [sc,FF]=fin(50+sumF(F),F,4,ci);
  return [sc,`${ch.tone} ${MS[ch.msign][0]}(${MS[ch.msign][1]})의 날에 태어나 ${MS[ch.msign][2]}의 힘을 지녔어요. ${y}년에는 260일마다 돌아오는 마야 탄생일이 ${rt.length}번(${ds}) 듭니다.${rt.length>=2?" 탄생일이 두 번 드는 해라 본래의 힘을 두 번 새로 채웁니다.":""}`,`탄생일 ${rt.length}번`,FF]}

/* =========================================================
   assemble: R = 가까운 미래(4시점), LY = 나이별(0~80세), LD = 10년 단위(0~70대)
   ========================================================= */
const ORC=[oSaju,oWest,oVedic,oNum,oMaya];
/* 화면 표시 점수: 내부 점수(약 30~98)를 75~99점으로 옮긴다. 판정·문구 기준은 내부 점수로 한다. */
const D=v=>Math.round(60+clamp((v-40)/57,0,1)*40);
/* 부드러운 곡선: 'x,y x,y' 점 문자열을 단조 3차 베지어 경로로 */
function smoothPath(pts){const p=pts.trim().split(/\s+/).filter(Boolean);return p.length<2?'':'M'+p.join(' L')}
let drawGraph=true;const drawCls=()=>drawGraph&&!reduceM?' draw':'';
const Y=dv=>30+(100-dv)/45*170;
const amp=(avg,k)=>Math.round(clamp(soft(60+(avg-56)*k,.6),32,98));
function summarize(v,k){const sc=v.map(x=>x[0]);const avg=sc.reduce((a,b)=>a+b)/sc.length;const sd=Math.sqrt(sc.reduce((a,b)=>a+(b-avg)**2,0)/sc.length);
  return {v,avg,mean:amp(avg,k),agree:Math.max(0,Math.round(100-sd*2.2))}}
let CH=null,R=null,RY=null,LY=null,LD=null,LS=null;const sel={money:0,love:0,work:0,health:0};let mode="near",selDec=0,netP=0,netC=0;
const AGES=81,DECS=8;
const nowAge=()=>{const n=new Date();return n.getFullYear()+(n.getMonth()+.5)/12-CH.birthYear};
function compute(){
  /* 1~10년 뒤를 해마다 계산(RY). R은 같은 값 */
  RY=Array.from({length:10},(_,i)=>CATS.map((c,ci)=>{const t=horizonDate(i+1);return summarize(ORC.map(o=>o(CH,t,ci)),1.8)}));
  R=HZ.map(h=>RY[h.off-1]);
  LY=Array.from({length:AGES},(_,a)=>{const t=lifeDate(CH,a);return CATS.map((c,ci)=>summarize(ORC.map(o=>o(CH,t,ci)),1.8))});
  LS=CATS.map((c,ci)=>LY.map((_,a)=>{let s=0,n=0;for(let k=-2;k<=2;k++){const r=LY[a+k];if(r){s+=r[ci].avg;n++}}return amp(s/n,2.6)}));
  LD=Array.from({length:DECS},(_,d)=>CATS.map((c,ci)=>{const yrs=LY.slice(d*10,d*10+10).map(r=>r[ci]);
    const v=ORC.map((o,oi)=>{const sc=yrs.map(r=>r.v[oi][0]);const m=sc.reduce((a,b)=>a+b)/sc.length;let bi=0;sc.forEach((x,i)=>{if(Math.abs(x-50)>Math.abs(sc[bi]-50))bi=i});
      const ex=yrs[bi].v[oi];const yr=Math.floor(CH.birthYear+d*10+bi+.5);
      return [Math.round(clamp(50+(m-50)*1.7,5,98)),`가장 두드러진 해는 <b>${yr}년(${d*10+bi}세)</b>. ${ex[1]}`,ex[2],yrs[5].v[oi][3]]});
    return summarize(v,1.8)}));
  lifeAdj();
}
/* 평생 점수 보정: 지나온 10년은 살짝 낮게, 지금부터 30년은 밝게, 60대 이후는 담담하게 */
function lifeAdj(){const na=nowAge();LD.forEach((row,d)=>{const a=d*10+5,t=a-na;row.forEach((c,ci)=>{let adj=t<-5?-3:7*(1-Math.min(1,Math.max(0,t)/35));if(a>=55)adj-=(a-55)*.25+(ci===3?(a-55)*.2:0);c.mean=Math.round(clamp(c.mean+adj,32,a>=60?82:98))})})}
const reduceM=matchMedia("(prefers-reduced-motion: reduce)").matches;

