  const sub=life?`${selDec*10}대 · ${decRange(selDec)}`:`${HZ[hi].n} · ${new Date().getFullYear()+HZ[hi].off}`;
  const na=nowAge();
  const nav=life?"":miniGraph(ci,hi);
  box.innerHTML=`<div class="cat-top"><div style="min-width:0"><h3>${c.n}<small>${sub}</small></h3><p class="head">${HEAD[c.k][tier(r.mean)]}</p>
   <div class="agree">${r.mean>=50?"가장 강하게 밀어주는 점술":"가장 강하게 경고하는 점술"}: ${lead} · 일치도 ${r.agree}%</div></div></div>${nav}
   <div class="dots">${r.v.map((x,i)=>`<span class="dot" style="--c:${M[i].c}"><i></i>${M[i].n} <b>${D(x[0])}</b></span>`).join("")}</div>
   ${life?"":`<details class="more catread" ${openState[c.k]?"open":""}><summary>1~10년 뒤와 평생 풀이 읽기 <span class="chev">⌄</span></summary><div class="cread">${catReading(ci)}</div></details>`}`;
  box.querySelectorAll(".mini-pt").forEach(b=>b.addEventListener("click",()=>{sel[c.k]=+b.dataset.h;renderCat(ci,true);renderTrend()}));
