function reportTags(ch){const d=ch.stems.d,dom=ch.cnt.indexOf(Math.max(...ch.cnt));const hits={};
  const add=(tag,sys,ev)=>{(hits[tag]=hits[tag]||{sys:new Set(),ev:[]});hits[tag].sys.add(sys);hits[tag].ev.push(ev)};
  add(TAG_DAY[d],"사주",`일간 ${ST[d]}${EL[SE[d]]}`);
  add(TAG_EL[dom],"사주",`${ELNAME[dom]}(${EL[dom]}) 기운 ${ch.cnt[dom]}개`);
  add(ch.strong?"lead":"bond","사주",ch.strong?"신강 사주":"신약 사주");
  if(ch.has.gui)add("help","사주","천을귀인");if(ch.has.munc)add("create","사주","문창귀인");if(ch.has.dohwa)add("bond","사주","도화");if(ch.has.yeokma)add("free","사주","역마");
  add(TAG_SIGN[sign(ch.sun)],"서양 점성술",`${ZOD[sign(ch.sun)]}자리 태양`);
  add(TAG_SIGN[sign(ch.moon)],"서양 점성술",`${ZOD[sign(ch.moon)]}자리 달`);
  if(ch.asc!=null)add(TAG_SIGN[sign(ch.asc)],"서양 점성술",`${ZOD[sign(ch.asc)]}자리 상승궁`);
  add(TAG_NAK[DL[ch.nk%9]],"베딕 점성술",`${NAK[ch.nk]} 낙샤트라`);
  if(ch.lagna!=null)add(TAG_SIGN[ch.lagna],"베딕 점성술",`${ch.chandra?"달 기준 라그나":"라그나"} ${ZOD[ch.lagna]}자리`);
  add(TAG_NUM[ch.lp],"수비학",`인생 수 ${ch.lp}`);if(ch.soul)add(TAG_NUM[ch.soul],"수비학",`영혼 수 ${ch.soul}`);if(ch.expr)add(TAG_NUM[ch.expr],"수비학",`표현 수 ${ch.expr}`);
  add(TAG_MAYA[ch.msign],"마야력",`${ch.tone} ${MS[ch.msign][0]}(${MS[ch.msign][1]})`);
  return Object.entries(hits).map(([k,v])=>({k,n:v.sys.size,sys:[...v.sys],ev:[...new Set(v.ev)]})).sort((a,b)=>b.n-a.n||b.ev.length-a.ev.length)}
function bestCell(){let b={v:-1};R.forEach((r,hi)=>r.forEach((c,ci)=>{const v=D(c.mean);if(v>b.v)b={v,hi,ci}}));
  const c=R[b.hi][b.ci];b.n=c.v.filter(x=>x[0]>=60).length;b.y=new Date().getFullYear()+HZ[b.hi].off;return b}
