 const SAN=x=>x%4,LIU=x=>(13-x)%12,el=s=>SE[s],gen=(x,y)=>(x+1)%5===y,ctl=(x,y)=>(x+2)%5===y,EN=['목','화','토','금','수'],SEL=['불','흙','공기','물'],COMP=[2,3,0,1];
