  if(ch.has.gui){const gb=ch.gui.find(b=>bs.includes(b));sal.push(`<p><strong>천을귀인${gb!=null?at(gb):""}</strong>은 사주에서 가장 귀하게 치는 길성이에요. 어려운 순간마다 손을 내미는 사람이 나타나고, 위기를 기회로 넘기는 힘이 있어요.</p>`)}
