/* Interpretation first; preserve the original technical statement as evidence. */
function readingParts(value){
 const source=String(value||'').replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"').trim();
 const tag=source.match(/^\[([^\]]+)\]\s*/);const content=source.replace(/^\[[^\]]+\]\s*/,'');
 const technical=/(?:일간|일지|월지|년지|시지|천간|지지|십성|십신|편인|정인|편재|정재|비견|겁재|식신|상관|편관|정관|신강|신약|원국|오행|하우스|상승궁|라그나|낙샤트라|다샤|개인년|개인일|인생 수|표현 수|영혼 수|촐킨|[木火土金水]\)|[甲乙丙丁戊己庚辛壬癸酉寅卯申戌亥]|태양.{0,12}자리|달.{0,12}자리|금성.{0,12}자리|수성.{0,12}자리|토성.{0,12}자리|목성.{0,12}자리)/;
 const main=[],basis=[];
 const sentences=content.split(/(?<=[.!?。])\s+|,\s+(?=(?:\d+하우스|달은|표현 수|영혼 수))/).filter(Boolean);
 for(const sentence of sentences){
  if(!technical.test(sentence)){main.push(sentence);continue}
  // Only remove a known chart clause when the remainder is independently readable.
  const splitters=[
   /^(?:[^.!?]{0,20}의 )?달은?\s*[^.!?]{0,30}?자리(?:의 달)?(?:은|는)?\s+(.+)$/,
   /^인생 수\s*\d+(?:은|는)\s+(.+)$/,
   /^(?:금성|달|수성|화성)이?\s+[^.!?]{0,30}?자리(?:이라|라|로|으로)\s+(.+)$/,
   /^(?:배우자 자리인 )?일지\s+[^.!?]{0,35}?(?:입니다|이에요|예요)\.\s*(.+)$/,

   /^(?:\S+:\s*)?(?:\S+ 점성술로 보면 |서양 점성술의 )?(?:태양|달|금성|수성|화성)(?:이|은|는)?\s*[^.!?]{0,85}?에 있어\s+(.+)$/,
   /^(?:\d+하우스(?:가|는)?|일과 사회적 무대인 \d+하우스는)\s+[^.!?]{0,45}?(?:이라|라|으로|로)\s+(.+)$/,
   /^상승궁\s+[^.!?]{0,35}?의 영향으로\s+(.+)$/,
   /^(?:\[사주\]\s*)?원국에 배우자 별인\s+[^.!?]{0,30}?개 있어\s+(.+)$/,
   /^(?:원국에서\s+)?[^.!?]{0,40}?개로 가장 많아\s+(.+)$/,
   /^감정:\s*달이\s+[^.!?]{0,30}?에 있어\s+(.+)$/
  ];
  const match=splitters.map(re=>sentence.match(re)).find(m=>m&&!technical.test(m[1]));
  if(match){main.push(match[1]);basis.push(sentence)}else basis.push(sentence);
 }
 return {main:main.join(' '),basis:basis.join(' '),label:tag?tag[1]:''};
}
function readingInline(value){const p=readingParts(value),E=topicEsc;let basis=p.basis;
 if(p.main&&basis){for(const sentence of p.main.split(/(?<=[.!?。])\s+/).filter(Boolean)){basis=basis.replace(sentence,'')}basis=basis.replace(/(태양|달|금성|수성|화성)이\s+/g,'$1 ').replace(/에 있어(?=\s|$)/g,'').replace(/\s+/g,' ').trim()}
 return (p.main?'<span class="reading-meaning">'+destinyMeaningHTML(p.main)+'</span>':'')+(basis?'<span class="reading-evidence"> — '+E(basis.replace(/[.。]\s*$/,''))+'</span>':'')}

function readingParagraph(value,cls=''){return '<p'+(cls?' class="'+cls+'"':'')+'>'+readingInline(value)+'</p>'}
function clarifyReading(root){if(!root)return;root.querySelectorAll('.r-prose p').forEach(p=>{p.innerHTML=readingInline(p.textContent)})}
/* Annual values stay unchanged. Every bar uses the same explicit 60–100 axis. */
function annualScoreChart(t){
 if(!t||!Array.isArray(t.rows)||t.rows.length<2||!/(연도|해마다).*점수/.test(t.cap||''))return '';
 const E=topicEsc,head=t.head||[],cols=head.map((h,i)=>i>0&&t.rows.every(r=>/^\s*\d+(?:\.\d+)?(?:점)?\s*$/.test(String(r[i])))?i:-1).filter(i=>i>0);
 if(!cols.length||!t.rows.every(r=>/^\d{4}년/.test(String(r[0]))))return '';
 const charts=cols.map(col=>{
 const values=t.rows.map(r=>Number(String(r[col]).replace('점','')));if(values.some(v=>!Number.isFinite(v)||v<60||v>100))return '';
 const best=Math.max(...values),name=head[col]==='점수'?(t.cap||'').split(' 연도별')[0]:head[col],W=520,H=310,L=42,R=22,T=28,B=48;
 const x=i=>L+i*(W-L-R)/(values.length-1),y=v=>T+(100-v)/40*(H-T-B);
 const ticks=[60,70,80,90,100].map(v=>'<line class="year-grid" x1="'+L+'" x2="'+(W-R)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text class="year-axis" x="'+(L-9)+'" y="'+(y(v)+5)+'" text-anchor="end">'+v+'</text>').join('');
 let points=values.map((v,i)=>'<g class="year-point'+(v===best?' best':'')+'"><title>'+E(t.rows[i][0])+' · '+E(name)+' '+v+'점</title><circle cx="'+x(i)+'" cy="'+y(v)+'" r="'+(v===best?4.5:3.5)+'"/><text class="year-value" x="'+x(i)+'" y="'+(y(v)-12)+'" text-anchor="middle">'+v+'</text><text class="year-axis" x="'+x(i)+'" y="'+(H-22)+'" text-anchor="middle">'+E(String(t.rows[i][0]).match(/^\d{4}/)[0].slice(2)+'년')+'</text></g>').join('');
 if(t.hideScores)points=points.replace(/<text class="year-value"[^>]*>[\s\S]*?<\/text>/g,'').replace(/ · [^<]*?\d+점/g,'');
 const label=name+' 연도별 점수: '+t.rows.map((r,i)=>String(r[0]).match(/^\d{4}/)[0]+'년 '+values[i]+'점').join(', ');
 return '<figure class="annual-score-chart annual-line-chart"><figcaption>'+E(name)+' · 연도별 흐름</figcaption><svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+E(t.hideScores?name+' · 연도별 흐름':label)+'"><title>'+E(name)+' · 연도별 흐름</title>'+ticks+'<line class="year-border" x1="'+L+'" x2="'+L+'" y1="'+T+'" y2="'+y(60)+'"/><polyline class="year-line" points="'+values.map((v,i)=>x(i)+','+y(v)).join(' ')+'"/>'+points+'</svg></figure>';
 }).filter(Boolean).join('');return charts?'<div class="annual-score-grid">'+charts+'</div>':'';
}

