 return (basis?'<section class="r-page rv3-ch report-score"><header class="rv3-hd"><span class="rv3-no">SCORE DETAILS</span><h2>'+E(year)+'년 '+E(data.category||'')+' 점수 계산서</h2></header>'+basis+'</section>':'')+'<section class="r-page rv3-ch report-method"><header class="rv3-hd"><span class="rv3-no">METHODOLOGY</span><h2>다섯 관점의 계산 방식</h2></header>'+reportInfoTable('계산 체계 요약',['체계','살펴보는 내용','사용 지표'],methods,'method-table')+'<h3>출생 정보의 적용 기준</h3>'+reportInfoTable('',['항목','적용 방식'],ranges,'range-table')+'</section>';
