/* ctx: worker.js buildRichReport에서 계산해 넘겨주는 값 */
function narrativeComprehensive(c) {
  const v = { name: c.name };
  const F = t => fill(t, v);
  const out = [];

  /* 1. 한눈에 보는 나 */
  out.push({
    kind: "summary", title: "한눈에 보는 나",
    lead: F(ONELINE[c.dom]),
    paras: [
      "다섯 가지 점술이 공통으로 말하는 건, " + c.common,
      fill(SUM_YEAR, { cat: CAT_KO[c.bestCat], y: c.bestYear }) + (c.mateYears.length ? " 사랑에서는 새 인연이나 약속의 신호가 가장 많이 겹치는 해가 " + c.mateYears[0].y + "년이에요." + (c.loveYear && c.loveYear !== c.mateYears[0].y ? " 이미 곁에 있는 관계가 가장 따뜻해지는 해는 " + c.loveYear + "년이에요." : "") : ""),
      "이 리포트는 사주, 서양 점성술, 베딕 점성술, 수비학, 마야력 다섯 가지로 {name}님을 함께 읽고, 여러 점술이 공통으로 가리키는 이야기를 중심으로 풀어 썼어요.".replace(/\{name\}/g, c.name)
    ],
    basis: c.basis.summary
  });

  /* 2. 성격 */
  out.push({
    kind: "personality", title: "타고난 성격과 기질",
    lead: "",
    paras: [F(INTRO[c.d]), F(SCENE[c.dom]), F(FEEL[c.moonEl]), F(LIGHT[c.topG][c.strong ? 0 : 1])],
    action: ACT[c.lack],
    basis: c.basis.personality
  });

  /* 3. 사랑과 인연 */
  const mateWhen = c.mateYears.length
    ? "시기로 보면 " + c.mateYears.map(m => m.y + "년(" + m.age + "살)").join("과 ") + "에 인연의 기운이 가장 뚜렷해요. 이 무렵 새로운 만남이 시작되거나, 만나던 사람과 미래를 약속하게 될 가능성이 커요. 이미 함께하는 사람이 있다면 관계가 한층 단단해지는 해로 읽어 주세요."
    : "앞으로 10년 안에서는 인연의 시기가 한 해에 몰리기보다 고르게 열려 있어요. 특정한 해를 기다리기보다, 마음이 가는 자리에 꾸준히 나가는 것이 좋은 인연을 만나는 가장 확실한 방법이에요.";
  out.push({
    kind: "partner", title: "사랑과 인연",
    lead: "",
    /* 2026-11-10: 성격(일간·오행)과 사랑(금성) 문단이 부딪힐 때 잇는 문장, 인연 신호 해와 애정 점수 최고 해를 구분하는 문장. */
    paras: [([2, 3, 4].includes(c.dom) && c.venusEl % 2 === 0 ? "평소에는 차분하고 신중해 보여도, 마음이 움직이면 달라져요. " : [0, 1].includes(c.dom) && c.venusEl % 2 === 1 ? "평소에는 앞장서고 활발한 편이지만, 마음을 여는 데는 시간이 걸려요. " : "") + F(LOVE[c.venusEl]), F(MATE[c.mateEl]), MEETP[c.descEl] + " " + mateWhen + (c.loveYear && !c.mateYears.some(m => m.y === c.loveYear) ? " 한편 애정 점수만 보면 " + c.loveYear + "년이 가장 높아요. 새로운 만남보다 지금 있는 관계가 따뜻해지는 해로 읽어 주세요." : "")],
    action: "이번 달에 평소 가지 않던 모임이나 자리에 한 번 나가 보세요. 인연은 늘 새로운 문 하나에서 시작돼요.",
    basis: c.basis.partner
  });

  /* 4. 일과 돈 */
  out.push({
    kind: "career", title: "일과 돈",
    lead: "",
    paras: [
      F(WORK[c.topG]),
      c.jobs ? "구체적으로는 " + c.jobs.replace(/\s*·\s+/g, ", ") + " 같은 분야가 {name}님의 기질과 잘 어울려요. 이미 다른 일을 하고 있다면, 지금 일 안에서 이런 성격의 역할을 맡아 보는 것도 좋은 방법이에요.".replace(/\{name\}/g, c.name) : "",
      F(MONEY[c.moneyTier]),
      c.workYear ? "일에서 가장 큰 기회가 오는 해는 " + c.workYear + "년이에요. 그 전 해까지 이력과 실력을 정리해 두면, 문이 열렸을 때 망설이지 않고 들어갈 수 있어요." : ""
    ],
    action: "지금 하는 일에서 가장 잘한 경험 세 가지를 적어 두세요. 다음 기회가 왔을 때 그대로 나를 소개하는 이야기가 돼요.",
    basis: c.basis.career
  });

  /* 5. 앞으로 10년 */
  const ys = c.keyYears.map((k, i) => ({ y: k.y, t: fill(YEAR[k.cat][i % 2], { name: c.name, y: k.y, age: k.age }) }));
  if (c.restYear) ys.push({ y: c.restYear.y, t: fill(REST, { y: c.restYear.y, age: c.restYear.age }) });
  if (c.turnYear) ys.push({ y: c.turnYear - 0.5, t: fill(TURN, { y: c.turnYear }) });
  out.push({
    kind: "flow", title: "앞으로 10년의 이야기",
    lead: "",
    paras: [FLOW_OPEN.replace(/\{name\}/g, c.name), ...ys.sort((a, b) => a.y - b.y).map(x => x.t)],
    basis: c.basis.flow
  });

  /* 6. 다섯 점술 */
  out.push({
    kind: "systems", title: "다섯 점술은 이렇게 봤어요",
    lead: "",
    paras: [
      "사주로 보면 {name}님은 " + SAJU_IMG[c.d] + "에 비유되는 사람이에요. 타고난 바탕이 " + (c.strong ? "단단해서 스스로 밀고 나가는 힘이 크고" : "섬세해서 좋은 사람과 환경을 만날 때 크게 자라고") + ", 앞으로는 " + c.goodTxt + "의 기운이 들어올 때 일이 잘 풀려요.",
      "서양 점성술로 보면 {name}님은 " + c.sunSign + "예요. " + SUN_TXT[c.sunIdx] + ", 그게 이 별자리가 타고난 힘이에요. 겉으로는 이런 모습이 먼저 보이고, 마음 깊은 곳에서는 " + c.moonSign + "처럼 " + ["뜨겁고 솔직한", "차분하고 안정을 원하는", "대화를 통해 정리하는", "깊고 섬세한"][c.moonEl] + " 감정이 움직여요.",
      c.planet ? "베딕 점성술로 보면 지금 {name}님은 " + PLANET_KO[c.planet] + josa(PLANET_KO[c.planet], "이", "가") + " 이끄는 시기를 지나고 있어요. " + PLANET_TXT[c.planet] + " 흐름이 " + c.planetEnd + "년까지 이어지니, 이 기간에는 그 방향으로 힘을 쓰는 게 좋아요." : "",
      "수비학으로 보면 {name}님의 생년월일은 " + c.lp + "이라는 숫자로 모여요. 이 숫자가 말하는 삶의 과제는 " + (LP_TXT[c.lp] || "자기만의 길을 찾는 것") + "이에요.",
      "마야력으로 보면 {name}님은 '" + c.mayaMeaning + "'" + josa(c.mayaMeaning, "을", "를") + " 뜻하는 기호를 타고났어요. 이 힘을 품고 있어서, 그 힘을 쓰는 일을 할 때 가장 자연스럽게 빛나요.",
      "다섯 가지 점술은 서로 다른 시대와 문화에서 왔지만, {name}님에 대해서는 같은 이야기를 하고 있어요. " + c.common
    ].map(t => t.replace(/\{name\}/g, c.name)),
    basis: c.basis.systems
  });

  /* 7. 마무리 */
  out.push({
    kind: "advice", title: "{name}님에게 전하는 이야기".replace("{name}", c.name),
    lead: "",
    paras: [
      F(CLOSE_GOOD[c.bestCat]),
      F(CLOSE_CARE[c.worstCat]),
      F("운명은 정해진 길이라기보다 내가 어떤 사람인지 알려 주는 지도에 가까워요. {name}님이 가진 힘을 알고, 언제 나아가고 언제 쉬어야 하는지 안다면 같은 길도 훨씬 덜 지치고 더 멀리 갈 수 있어요. 이 리포트가 그 길에 작은 등불이 되었으면 좋겠어요.")
    ],
    action: "이 리포트에서 마음에 남은 문장 하나를 메모장에 적어 두세요. 힘든 날 다시 꺼내 보면 생각보다 큰 힘이 돼요.",
    basis: []
  });

  return out;
}

