const SYEAR = [
  "{y}년({age}살)은 공부가 결과로 이어지기 쉬운 해예요. 시험이나 자격, 진학처럼 목표가 있다면 이 해에 맞춰 준비해 두면 좋아요.",
  "{y}년({age}살)에는 배우는 속도가 빨라져요. 새로운 분야를 시작하거나 어려웠던 과목을 다시 잡기에 좋은 해예요.",
  "{y}년({age}살)은 좋은 스승이나 함께 공부할 사람을 만나기 쉬운 해예요. 혼자 하던 공부를 함께하는 방식으로 바꿔 보면 큰 도움이 돼요."
];
const SREST = "{y}년({age}살)은 공부에서 기초를 다지는 해예요. 눈에 띄는 성과보다 바탕을 탄탄하게 만드는 데 힘을 쓰면, 그다음 해에 훨씬 크게 도약할 수 있어요.";
const LAST_ACT = "이 리포트에서 마음에 남은 문장 하나를 메모장에 적어 두세요. 힘든 날 다시 꺼내 보면 생각보다 큰 힘이 돼요.";

function narrativeStudy(c) {
  const v = { name: c.name }, F = t => fill(t, v), out = [];
  out.push({ kind: "core", title: "공부할 때의 나", lead: F(SSTYLE[c.dom]).split(/(?<=[.!?])\s+/)[0],
    paras: [F(SSTYLE[c.dom]), F(SENV[c.topG])], basis: c.basis.core });
  out.push({ kind: "method", title: "나에게 맞는 공부법", lead: "", paras: [F(SMETHOD[c.dom])],
    action: "이번 주 공부 계획을 하루 단위로 쪼개 적고, 끝낸 날에는 체크 표시를 해 보세요.", basis: [] });
  const ys = c.studyYears.map((k, i) => ({ y: k.y, t: fill(SYEAR[i % 3], { y: k.y, age: k.age }) }));
  if (c.studyRest) ys.push({ y: c.studyRest.y, t: fill(SREST, { y: c.studyRest.y, age: c.studyRest.age }) });
  out.push({ kind: "timing", title: "앞으로 10년, 배움의 흐름", lead: "",
    paras: [F("배움에도 때가 있어요. 실력이 쑥 오르는 해가 있고, 기초를 다지며 준비하는 해가 있어요. {name}님에게 특히 중요한 해들을 순서대로 짚어 볼게요."), ...ys.sort((a, b) => a.y - b.y).map(x => x.t)],
    basis: c.basis.timing });
  out.push({ kind: "caution", title: "공부에서 조심할 점", lead: "", paras: [F(SCARE[c.dom])],
    action: "지금 보고 있는 교재나 강의 중 하나만 남기고, 끝까지 마치는 날짜를 달력에 적어 두세요.", basis: [] });
  out.push({ kind: "advice", title: F("{name}님에게 전하는 이야기"), lead: "",
    paras: [F("공부는 남과의 경쟁처럼 보이지만, 결국은 어제의 나를 조금씩 넘어서는 일이에요. {name}님에게 맞는 방법을 알고 꾸준히 이어 가면, 지금은 멀어 보이는 목표도 생각보다 빨리 가까워져요. 오늘 한 페이지가 내일의 결과를 만들어요.")],
    action: LAST_ACT, basis: [] });
  return out;
}

