function socialPlayData(list){
 const style=[['개척 대장','아이디어 씨앗'],['분위기 점화자','리액션 요정'],['든든한 중심','안부 지킴이'],['계획 해결사','취향 감별사'],['대화 수집가','조용한 연결자']];
 const activity=['처음 가 보는 동네 산책과 작은 체험 수업','노래 맞히기나 몸으로 설명하는 팀 게임','각자 좋아하는 간식 하나씩 가져오는 소풍','규칙이 간단한 보드게임과 취향별 맛집 투표','서로 고른 음악을 듣고 이유를 나누는 카페 시간'];
 const mission=['아직 안 해 본 활동 하나를 제안하기','오늘 제일 웃겼던 순간을 한 문장으로 남기기','모두 편하게 먹을 간식과 쉬는 시간 챙기기','비용과 일정을 한눈에 보이게 정리하기','말이 적었던 사람에게 부담 없는 질문 하나 건네기'];
 const dom=c=>c.cnt.indexOf(Math.max(...c.cnt));
 const counts=[0,0,0,0,0];list.forEach(c=>counts[dom(c)]++);
 const order=counts.map((n,i)=>({n,i})).filter(x=>x.n).sort((a,b)=>b.n-a.n||a.i-b.i);
 return {nick:list.map(c=>style[dom(c)][c.strong?0:1]),activities:order.slice(0,2).map(x=>activity[x.i]),missions:list.map(c=>mission[dom(c)]),same:order.length===1};
}
function friendReportData(a,b,res){
 const names=[a.inp.name||'나',b.inp.name||'친구'],roles=[groupRole(a),groupRole(b)];
 const dom=c=>c.cnt.indexOf(Math.max(...c.cnt)),same=dom(a)===dom(b);
 const style=['새로운 활동과 제안을 나누는 것','반응과 고마움을 말로 전하는 것','꾸준히 안부를 묻고 익숙한 시간을 갖는 것','약속과 서로의 기준을 분명히 하는 것','차분히 듣고 혼자 생각할 시간을 주는 것'];
 const sections=[
  {kind:'core',question:'우리 우정의 핵심',lead:names.join('님과 ')+'님의 우정 비교 지표는 '+res.total+'점이에요.',paragraphs:[same?'두 사람은 강한 오행이 같아 편한 활동이나 반응 방식에서 공통점을 찾아볼 수 있어요. 비슷한 만큼 서로 양보하기 어려운 기준도 확인해 보세요.':'두 사람의 강한 오행이 달라 서로 다른 방식으로 관계에 기여하는 조합으로 읽어요. 나와 다른 반응을 무관심으로 단정하기보다 이유를 물어보세요.'],basis:['강한 오행: '+names.map((n,i)=>n+' '+ELK[dom([a,b][i])]).join(' · ')]},
  {kind:'communication',question:'서로에게 편한 대화와 거리',lead:'연락의 양보다 서로 편한 방식을 맞춰보세요.',paragraphs:names.map((n,i)=>n+'님은 '+style[dom([a,b][i])]+'을 대화의 출발점으로 삼아볼 수 있어요.'),action:'답장이 늦을 때의 기준과 만나고 싶은 빈도를 한 번씩 이야기해 보세요.'},
  {kind:'advice',question:'오래 편하게 지내는 작은 약속',lead:'도움과 부탁에도 서로의 여유를 먼저 확인해 보세요.',paragraphs:[names[0]+'님은 '+roles[0][0]+', '+names[1]+'님은 '+roles[1][0]+'의 역할을 시도해 볼 수 있어요. 역할은 고정하지 말고 번갈아 맡아보세요.','서운할 때는 “너는 항상” 대신 최근 있었던 일 하나와 내가 바라는 행동 하나를 전하세요. 함께 쓰는 돈과 취소 약속은 미리 정하면 편해요.'],action:'이번 주에는 함께 할 짧은 활동 하나를 정하고, 고마웠던 점을 한 문장씩 나눠보세요.'}
 ];
 const play=socialPlayData([a,b]);
 sections.push(
  {kind:'friend-chemistry',question:'우리 둘이 친구인 이유',lead:'',cast:socialDogCast([a,b]),paragraphs:[play.same?'닮은 리듬으로 웃음 포인트가 통하는 조합이에요. 취향이 겹칠 때는 함께 깊게 파보고, 의견이 갈리면 먼저 양보할 항목을 하나씩 정해 보세요.':'서로 다른 재주가 만나는 조합이에요. 한 사람이 시작한 아이디어를 다른 사람이 어떻게 살려 주는지 찾아보세요.',...names.map((n,i)=>n+'님이 함께할 때의 강점: '+roles[i][1])]},
  {kind:'friend-play',question:'둘이 만나면 해 볼 것',lead:'다음 약속에 하나만 골라 보세요.',paragraphs:play.activities,action:'각자 하고 싶은 활동에 한 표씩 주고, 의견이 다르면 이번과 다음 약속에 번갈아 해 보세요.'},
  {kind:'friend-mission',question:'친구 사용 설명서 맞혀보기',lead:'서로 답을 적은 뒤 동시에 공개해 보세요.',paragraphs:['친구가 지쳤을 때 원하는 것은? 조용히 듣기 / 해결책 찾기 / 함께 놀기','약속이 취소되면 더 반가운 것은? 바로 다음 날짜 잡기 / 편하게 쉬라고 하기','친구가 생각하는 내 장점 하나를 먼저 예상하고, 실제 답과 비교해 보세요.'],action:'틀린 답은 놀릴 소재보다 새로 알게 된 취향으로 기억해 주세요.'}
 );
 return {title:names.join('님과 ')+'님의 우정 리포트',summary:[sections[0].lead,same?'비슷한 방식을 강점으로, 서로의 기준은 말로 확인해요.':'다른 반응을 존중하며 각자의 강점을 나눠요.',sections[2].action],sections,years:[],category:'우정',birthCharts:[a,b],version:'friend-2026-11-11-v17',note:'점수는 기존 두 사람 궁합 계산을 재사용한 자체 비교 지표이며 우정의 깊이나 지속 기간을 예측하지 않아요. 출생 시각·장소 미상 항목은 참고값이며, 실제 대화와 서로의 선택을 우선해 주세요. 미래 예측력은 검증되지 않았어요.',body:''}
}
function groupReportData(list,r){
 if(list.length<3||list.length>8)throw new Error('모임은 3~8명이 필요해요.');
 const nm=list.map((c,i)=>groupName(c,i));
 const pairName=p=>nm[p.i]+' · '+nm[p.j],even=r.spread===0;
 const sections=[
  {kind:'core',question:'우리 모임의 조합',lead:list.length+'명의 모임 비교 지표는 '+r.total+'점이에요.',paragraphs:[even?'모든 두 사람 조합의 점수가 같아요. 특정 조합을 더 좋거나 나쁘다고 구분하지 않아요.':'두 사람 조합의 최고·최저 점수 차이는 '+r.spread+'점이에요. '+pairName(r.best)+' 조합은 '+r.best.total+'점, '+pairName(r.worst)+' 조합은 '+r.worst.total+'점으로 읽어요. 점수가 낮다고 누군가를 배제할 이유는 아니에요.','구성원 사이의 점수를 평균 낸 값이며 실제 모임의 분위기나 지속 기간을 정하지 않아요.']},
  {kind:'role',question:'각자 기여할 수 있는 역할',lead:'각자의 강점을 바탕으로 역할을 나눠보세요.',paragraphs:['강한 오행과 일간 강약을 역할의 상징으로 옮겼어요. 실제 선호를 물어보고 준비·진행·정리를 돌아가며 맡아보세요.'],table:{cap:'구성원별 역할 제안',head:['이름','역할','강점'],rows:list.map((c,i)=>[nm[i],r.roles[i][0],r.roles[i][1]])}},
  {kind:'pairs',question:'두 사람씩 살펴보기',lead:'누가 더 중요한지가 아니라 서로 다른 조합을 비교해요.',paragraphs:['점수 차이가 있는 조합은 결정 속도나 말투, 약속 기준이 서로 다른지 확인해 보세요. 소외되는 사람이 없도록 대화할 기회와 자리를 고르게 나눠요.'],table:{cap:'전체 두 사람 조합 · 자체 비교 지표',head:['두 사람','점수'],rows:r.pairs.slice().sort((a,b)=>b.total-a.total).map(p=>[pairName(p),p.total+'점'])}},
  {kind:'advice',question:'다음 모임 전에 정할 세 가지',lead:'돈·시간·역할을 미리 맞추면 함께하기 편해져요.',paragraphs:['회비와 정산: 1인 예산, 결제 담당, 정산 날짜를 단체 대화방에 남겨요.','일정과 취소: 가능한 날짜를 함께 고르고 불참·취소 기준을 정해요.','역할과 의견: 진행·예약·정리를 순환하고 각자 원하는 활동을 하나씩 제안해요.'],action:'다음 날짜를 잡기 전에 이번 모임에서 좋았던 점과 바꾸고 싶은 점을 하나씩 나눠보세요.'}
 ];
 const play=socialPlayData(list);
 sections.push(
  {kind:'group-cast',question:'우리 모임 예능 캐스팅',lead:'이 조합으로 모이면 이런 장면이 떠올라요.',cast:socialDogCast(list),paragraphs:[],table:{cap:'이번 모임 캐릭터와 미션',head:['이름','별명','오늘의 미션'],rows:nm.map((n,i)=>[n,socialDogCast(list)[i].label,play.missions[i]])},action:'별명이 마음에 안 들면 서로 더 잘 맞는 이름을 붙여 주세요. 다음 모임에는 역할도 바꿔 보세요.'},
  {kind:'group-play',question:'우리 모임에 어울리는 놀거리',lead:play.same?'취향이 모이는 활동 하나를 깊게 즐겨 보세요.':'서로 다른 취향을 번갈아 즐길 코스를 만들어 보세요.',paragraphs:play.activities,action:'각자 활동 하나를 더 제안하고, 모두가 참여할 수 있는 난이도와 예산으로 골라 보세요.'},
  {kind:'group-mission',question:'단톡방에서 시작하는 10분 미션',lead:'다음 모임 전에 한 번씩 답해 보세요.',paragraphs:['취향 빙고: 좋아하는 음식·휴일 활동·듣는 음악을 하나씩 적고 가장 많이 겹친 취향을 찾아요.','칭찬 이어달리기: 명단 순서대로 다음 사람에게 함께해서 좋았던 순간 하나를 전해요. 마지막 사람은 첫 사람에게 전해요.','숨은 공통점 찾기: 처음에는 달라 보이는 두 사람이 대화해 의외의 공통점 세 개를 찾아요.'],action:'답하기 어려운 질문은 패스해도 좋아요. 모든 사람이 한 번씩 말할 수 있게 차례를 나눠 주세요.'}
 );
 return {title:list.length+'명의 모임 리포트',summary:[sections[0].lead,'역할은 강점의 제안으로 읽고 돌아가며 맡아요.',sections[3].lead],sections,years:[],category:'모임',note:'전통 차트의 두 사람 비교 점수를 평균 낸 참고 지표예요. 출생 시각·장소 미상 항목은 참고값이며 모임의 수명이나 개인의 실제 성격을 단정하지 않아요. 미래 예측력은 검증되지 않았어요.',birthCharts:list,version:'group-2026-11-11-v17',body:''}
}

/* ===== 카카오 친구 초대 링크: 친구가 로그인하고 내 정보를 저장하면 서로의 궁합이 보인다 ===== */
const PAIRKEY='oracle-pair';
function pairUrl(code){return SHARE_URL+'?c='+code}

let cmpWatchTimer=null,cmpWatching=false;
function cmpRemember(code){try{localStorage.setItem('oracle-pair-request',JSON.stringify({code,userId:accountUser.id,created:Date.now()}))}catch(_){}}
function cmpWatch(code){clearInterval(cmpWatchTimer);let busy=false;const check=async()=>{if(busy||document.hidden||!accountUser||!CH||cmpWatching)return;busy=true;cmpWatching=true;try{if(await cmpPairCheck(code,document.querySelector('[data-pcheck="'+code+'"]')?.parentNode.querySelector('.cmp-pair-msg'))){clearInterval(cmpWatchTimer);cmpWatchTimer=null;try{localStorage.removeItem('oracle-pair-request')}catch(_){}}}catch(_){}finally{busy=false;cmpWatching=false}};cmpWatchTimer=setInterval(check,5000);check()}
async function cmpMakeLink(btn){
 if(!requireSavedProfile())return;
 const out=btn.closest('.cmp-form').querySelector('.cmp-pair');btn.disabled=true;
 try{
  const d=await accountAPI('/pair',{kind:CMPKIND}),url=pairUrl(d.code);
  out.innerHTML='<p class="cmp-note">아래 링크를 상대방에게 보내주세요. 상대방이 카카오 로그인 후 출생 정보를 저장하면 이 화면에 자동으로 입력돼요. 참여하면 서로의 출생 정보와 궁합이 공유돼요.</p><p class="cmp-link"><input type="text" readonly value="'+topicEsc(url)+'" aria-label="입력 요청 링크"></p><button type="button" data-pcopy>링크 복사</button> <button type="button" data-pcheck="'+d.code+'">입력 확인하기</button><p class="cmp-priv cmp-pair-msg" aria-live="polite">상대방의 입력을 기다리고 있어요…</p>';
  out.querySelector('[data-pcopy]').onclick=async()=>{const field=out.querySelector('input');try{await navigator.clipboard.writeText(url);out.querySelector('.cmp-pair-msg').textContent='링크를 복사했어요. 상대방에게 보내주세요.'}catch(_){field.focus();field.select();out.querySelector('.cmp-pair-msg').textContent='링크를 선택했어요. 직접 복사해 주세요.'}};
  cmpRemember(d.code);cmpWatch(d.code);
 }catch(e){out.innerHTML='<p class="cmp-priv">'+topicEsc(e.message||'링크를 만들지 못했어요.')+'</p>'}finally{btn.disabled=false}
}
function cmpFillShared(profile){
 const form=document.querySelector('#cmpOne #compatibility-form');if(!form)return;
 const el=form.elements;el.partnerName.value=profile.name||'';el.partnerRoman.value=profile.roman||'';el.partnerRoman.dataset.edited='1';
 [...el.partnerSex].forEach(r=>r.checked=r.value===profile.sex);el.partnerDate.value=profile.date||'';el.partnerTime.value=profile.notime?'':profile.time||'';el.partnerNoTime.checked=!!profile.notime;el.partnerTime.disabled=!!profile.notime;
 el.partnerNoPlace.checked=!!profile.place?.none;el.partnerPlace.disabled=!!profile.place?.none;
 if(profile.place&&!profile.place.none){let opt=el.partnerPlace.querySelector('option[value="shared"]');if(!opt){opt=document.createElement('option');opt.value='shared';el.partnerPlace.append(opt)}opt.textContent=profile.place.name||'상대방이 입력한 출생지';el.partnerPlace.value='shared';form.dataset.sharedPlace=JSON.stringify(profile.place)}
 el.partnerSave.checked=false;
}

function pairChart(m,i){const p=typeof m.profile==='string'?JSON.parse(m.profile):m.profile;
 return buildChart(Object.assign({},p,{name:p.name||m.nickname||('참여자 '+(i+1))}))}

async function cmpPairCheck(code,msgEl){
 const d=await accountAPI('/pair?code='+encodeURIComponent(code));
 const others=(d.members||[]).filter(m=>!m.me);
 if(!others.length){if(msgEl)msgEl.textContent='아직 친구가 들어오지 않았어요. 친구가 로그인하고 내 정보를 저장하면 여기에 바로 보여요.';return false}
 const kind=d.kind==='group'?'group':d.kind==='friend'?'friend':'love';
 if(kind==='group'){GROUP=others.map(pairChart).filter((c,i,a)=>!sameGroupPerson(c,CH)&&a.findIndex(x=>sameGroupPerson(c,x))===i);cmpSetKind('group');groupRefresh();groupRender()}
 else{const other=pairChart(others[0],1);COMPAT={b:other,res:compatScore(CH,other),mode:'match',kind};cmpSetKind(kind);cmpFillShared(other.inp);cmpShowOne((other.inp.name||'친구')+'님')}
 return true}

function cmpShowOne(label,scroll=true){
 if(COMPAT&&COMPAT.mode==='match'&&CMPKIND==='friend')COMPAT.kind='friend';
 if(COMPAT?.kind==='friend'&&scroll){const pair=COMPAT,out=document.getElementById('friendRoleOut');if(out){const token=String(Date.now())+Math.random();out.dataset.reveal=token;out.innerHTML=socialRevealHTML();out.scrollIntoView({behavior:soft(),block:'nearest'});setTimeout(()=>{if(COMPAT===pair&&out.isConnected&&out.dataset.reveal===token)cmpShowOne(label,false);},900);return;}}

 if(COMPAT?.kind==='friend'){const out=document.getElementById('friendRoleOut')||document.querySelector('#cmpOne .cmp-result');if(out){out.innerHTML=socialResultHTML([CH,COMPAT.b]);collapseFriendInputs(out);if(scroll)out.scrollIntoView({behavior:soft(),block:'nearest'});}return;}
 const res=COMPAT.res,out=document.querySelector('#cmpOne .cmp-out')||document.querySelector('#cmpOne .cmp-result');if(!out)return;cmpCollapse(out);
 const lv=res.total>=88?'아주 잘 맞는 편':res.total>=80?'잘 맞는 편':res.total>=74?'서로 편안한 사이':'맞춰 갈수록 좋아지는 사이';
 out.innerHTML='<div class="cmp-score"><span>'+topicEsc(J(label,'과','와'))+' 나의 '+(COMPAT.kind==='friend'?'우정 ':'')+'궁합</span><em>'+lv+'</em></div>'+
  '<p class="cmp-note">잘 맞는 점과 다섯 점술별 근거는 <b>'+(COMPAT.kind==='friend'?'우정':'궁합')+' 리포트</b>에서 확인해 주세요.</p><p class="cmp-price">'+LAUNCH_PRICE(TOPIC_REPORT_PRICE)+'</p><button type="button" class="cmp-open" data-cmp-open>리포트 보기 →</button>';
 if(scroll)out.scrollIntoView({behavior:soft(),block:'nearest'})}

function cmpSetKind(k){
 CMPKIND=k;if(k!=='love')FRIENDKIND=k;
 {const one=document.getElementById('cmpOne'),want=k==='love'?'love':'friend';if(one&&k!=='group'&&one.dataset.kind!==want){one.dataset.kind=want;one.innerHTML=cmpOneInner(want);if(COMPAT&&COMPAT.mode==='match'&&(COMPAT.kind==='friend')!==(k==='friend'))COMPAT=null}}
 document.getElementById('cmpOne')?.classList.toggle('friend-controls',k==='friend');
 const intro=document.querySelector('#tab-match .topic-intro');if(intro){const h=intro.querySelector('h3'),p=intro.querySelector('p');if(h)h.textContent=k==='group'?'우리 모임의 역할과 캐릭터':k==='friend'?'우리의 역할과 어울리는 캐릭터':'우리 둘은 어떤 점에서 잘 맞을까?';if(p)p.textContent=k==='love'?'두 사람의 관계 성향과 조율할 점을 함께 살펴봐요.':'서로의 역할과 어울리는 캐릭터를 보여드려요. 함께하는 조합에 따라 상대적인 역할과 캐릭터가 달라져요.';}
 if(COMPAT?.mode==='match'&&k!=='group'){COMPAT.kind=k;cmpShowOne((COMPAT.b.inp.name||'친구')+'님',false)}
 /* 궁합 탭(연인)은 종류 선택 없이 바로 폼, 우정 탭은 '우정 / 모임' 두 가지 */
 document.querySelectorAll('.cmp-kind').forEach(box=>{box.hidden=k==='love'});
 document.querySelectorAll('[data-ck]').forEach(b=>{const visible=b.dataset.ck!=='love';b.hidden=!visible;b.style.display=visible?'':'none';b.setAttribute('aria-pressed',String(b.dataset.ck===k))});
 const note=document.getElementById('cmpKindNote');if(note)note.textContent=CMP_NOTE[k];
 const one=document.getElementById('cmpOne'),g=document.getElementById('cmpGroup');
 if(one)one.hidden=k==='group';if(g)g.hidden=k!=='group';const friendOut=document.getElementById('friendRoleOut');if(friendOut){friendOut.hidden=k!=='friend';if(k==='friend'&&!COMPAT)friendOut.innerHTML=socialPlaceholderHTML(2);}
 if(k==='group')groupRefresh()}

/* 2026-11-12: 궁합·재회·우정 공통 배치. 결과 자리 → 접기 '상대 선택하기'(저장한 상대 + 확인 버튼) → 접기 '상대 정보 입력하기'. 결과가 나오면 둘 다 접는다. */
function cmpPanelsHTML(kind){const L={friend:['친구 선택하기','친구 정보 입력하기','우리 관계 확인하기','친구'],love:['상대 선택하기','상대 정보 입력하기','궁합 확인하기','상대'],reunion:['상대 선택하기','상대 정보 입력하기','재회 흐름 확인하기','상대']}[kind],has=partnerList().length;
 return '<div class="cmp-wrap" data-kind="'+kind+'">'+(kind==='friend'?'':'<div class="cmp-out" aria-live="polite"></div>')+
  '<details class="cmp-pick-panel"'+(has?' open':'')+'><summary>'+L[0]+'</summary><section class="chart-form cmp-form"><div class="cmp-saved">'+partnerSavedHTML(false)+'</div><p class="friend-empty">저장한 '+L[3]+'가 아직 없어요. 아래 \''+L[1]+'\'에서 추가해 주세요.</p><p class="friend-selection-status" role="status"></p><button type="button" class="cmp-open" data-friend-result>'+L[2]+'</button></section></details>'+
  '<details class="cmp-add-panel"'+(has?'':' open')+'><summary>'+L[1]+'</summary>'+compatFormHTML(kind==='reunion'?'reunion':'match',kind)+'</details></div>'}
function cmpCollapse(el){const w=el&&el.closest?el.closest('.cmp-wrap')||el.closest('#cmpOne,.topic')?.querySelector('.cmp-wrap'):null;if(w)w.querySelectorAll('details').forEach(d=>d.open=false)}
/* 2026-11-12: 우정(두 사람)은 모임과 같은 배치. '친구 선택하기'(저장한 친구 + 우리 관계 확인하기)와 '친구 정보 입력하기'(공유 요청 + 직접 입력) 두 접기 영역, 결과가 나오면 둘 다 접는다. */
function cmpOneInner(k){return '<div id="friendRoleOut" aria-live="polite"'+(k==='friend'?'':' hidden')+'>'+socialPlaceholderHTML(2)+'</div>'+cmpPanelsHTML(k==='friend'?'friend':'love')}
function matchPanelHTML(){
 return '<div class="cmp-kind" role="group" aria-label="우정 궁합 종류"'+(CMPKIND==='love'?' hidden':'')+'>'+Object.keys(CMP_KIND).map(k=>'<button type="button" data-ck="'+k+'" aria-pressed="'+(k===CMPKIND)+'">'+CMP_KIND[k]+'</button>').join('')+'</div>'+
  '<p class="cmp-kind-note" id="cmpKindNote">'+CMP_NOTE[CMPKIND]+'</p>'+
  '<div id="cmpOne" data-kind="'+(CMPKIND==='love'?'love':'friend')+'" class="'+(CMPKIND==='friend'?'friend-controls':'')+'"'+(CMPKIND==='group'?' hidden':'')+'>'+cmpOneInner(CMPKIND==='love'?'love':'friend')+'</div>'+
  '<div id="cmpGroup"'+(CMPKIND==='group'?'':' hidden')+'><div id="cmpGroupOut" aria-live="polite">'+socialPlaceholderHTML(3)+'</div><details class="group-members-panel" open><summary>모임 구성원</summary><section class="chart-form cmp-form"><div id="cmpGroupList">'+groupListHTML()+'</div></section></details><details class="group-add-panel" open><summary>모임에 사람 추가하기</summary>'+compatFormHTML('group')+'</details></div>'}

document.addEventListener('click',e=>{
 const k=e.target.closest('[data-ck]');if(k){cmpSetKind(k.dataset.ck);return}
 const mk=e.target.closest('[data-pmake]');if(mk){cmpMakeLink(mk);return}
 const pc=e.target.closest('[data-pcheck]');if(pc){const msg=pc.parentNode.querySelector('.cmp-pair-msg');pc.disabled=true;if(msg)msg.textContent='확인하고 있어요…';
  cmpPairCheck(pc.dataset.pcheck,msg).catch(err=>{if(msg)msg.textContent=err.message||'확인하지 못했어요.'}).finally(()=>{pc.disabled=false});return}
 const gd=e.target.closest('[data-gdel]');if(gd){GROUP.splice(+gd.dataset.gdel,1);GROUPRES=null;groupRefresh();const o=document.getElementById('cmpGroupOut');if(o)o.innerHTML=socialPlaceholderHTML(3);return}
 if(e.target.closest('[data-gcalc]')){groupRender();return}
 if(e.target.closest('[data-gopen]')){openGroupReport(e.target.closest('[data-gopen]'));return}
});

/* 링크로 들어온 친구: 주소창에서 코드를 지우고, 로그인·정보 저장이 끝나면 합류시킨다. */
(function(){try{
 const u=new URL(location.href),c=u.searchParams.get('c');
 if(c&&/^[a-f0-9]{12}$/.test(c)){sessionStorage.setItem(PAIRKEY,c);u.searchParams.delete('c');history.replaceState(null,'',u.pathname+u.search+u.hash)}
}catch(_){}})();

/* 초대 링크로 들어온 사람이 이미 출생 정보를 저장해 둔 경우: 바로 합류하지 않고 서로 보는 데 동의하는지 먼저 묻는다. 링크를 보낸 사람은 만들 때 동의한 것으로 본다. */
function pairConsent(){return new Promise(res=>{let d=$('pairConsentDialog');if(!d){d=document.createElement('dialog');d.id='pairConsentDialog';d.className='login-save-dialog pair-consent';d.setAttribute('aria-labelledby','pairConsentTitle');d.innerHTML='<h2 id="pairConsentTitle">친구가 보낸 궁합 링크예요</h2><p>동의하면 저장된 내 출생 정보로 궁합을 계산하고, 결과와 출생 정보가 링크를 보낸 사람에게도 보여요.</p><p class="fine">링크를 보낸 사람은 링크를 만들 때 이미 동의한 것으로 봐요.</p><div class="login-save-btns"><button type="button" data-pair-no>나중에</button><button type="button" class="primary" data-pair-yes>동의하고 궁합 보기</button></div>';document.body.append(d);d.querySelector('[data-pair-yes]').onclick=()=>d.close('yes');d.querySelector('[data-pair-no]').onclick=()=>d.close('no')}
 d.onclose=()=>res(d.returnValue==='yes');d.returnValue='';d.showModal()})}
async function cmpPairBoot(){
 let code='';try{code=sessionStorage.getItem(PAIRKEY)||''}catch(_){}
 if(!code){try{const pending=JSON.parse(localStorage.getItem('oracle-pair-request')||'null');if(pending&&pending.userId===accountUser?.id&&Date.now()-pending.created<7*864e5)cmpWatch(pending.code)}catch(_){}return}
 if(!accountUser){accountNotice('친구가 보낸 궁합 링크예요. 카카오로 로그인하고 내 출생 정보를 저장하면 두 사람의 궁합이 서로에게 보여요.');return}
 if(!accountUser.profile){accountNotice('궁합 링크로 들어왔어요. 출생 정보를 입력하고 ‘내 정보 저장’을 누르면 친구와의 궁합이 바로 나와요.');return}
 if(!(await pairConsent())){try{sessionStorage.removeItem(PAIRKEY)}catch(_){}accountNotice('궁합 링크 참여를 미뤘어요. 보고 싶어지면 친구가 보낸 링크를 다시 열어 주세요.');return}
 try{
  await accountAPI('/pair/join',{code});
  try{sessionStorage.removeItem(PAIRKEY)}catch(_){}
  if(!CH)return;
  setTab('match');
  if(await cmpPairCheck(code,null))accountNotice('친구와의 궁합이 준비됐어요. 궁합 탭에서 확인해 주세요.');
 }catch(e){accountNotice('궁합 링크를 여는 데 실패했어요. 잠시 뒤 다시 시도해 주세요.')}}

/* 초대 링크로 들어온 비로그인 친구: 입력창을 바로 열고, 제출하면 카카오 로그인 안내를 띄운다. */
(function(){try{
 if(!sessionStorage.getItem(PAIRKEY)||localStorage.getItem('oracle-session'))return;
 document.body.classList.add('app-entered');const ab=document.getElementById('askbox');if(ab)ab.open=true;
 accountNotice('친구가 보낸 궁합 링크예요. 내 정보를 입력하면 카카오로 로그인한 뒤 두 사람의 궁합을 볼 수 있어요.');
 document.addEventListener('submit',e=>{
  if(e.target.id!=='ask'||localStorage.getItem('oracle-session'))return;
  e.preventDefault();e.stopImmediatePropagation();
  const err=checkForm();if(err){document.getElementById('err').textContent=err;return}
  const d=document.getElementById('loginSaveDialog');
  d.querySelector('h2').textContent='카카오로 로그인해야 궁합을 볼 수 있어요';
  d.querySelector('p').textContent='입력한 정보를 카카오 계정에 저장하면, 친구와의 궁합이 바로 보여요.';
  document.getElementById('loginSaveAgree').checked=true;d.showModal()},true);
}catch(_){}})();

